#
# MatrixGenerator.psm1
#
# Generates a GitHub Actions `strategy.matrix` from a declarative configuration.
#
# The configuration mirrors a real GitHub `strategy` block so it is intuitive:
#
#   {
#     "matrix": {
#       "os":   ["ubuntu-latest", "windows-latest"],   # dimension
#       "node": ["18", "20"],                            # dimension
#       "include": [ { ... } ],                          # optional add rules
#       "exclude": [ { ... } ]                           # optional remove rules
#     },
#     "max-parallel": 4,        # optional, passed through to strategy.max-parallel
#     "fail-fast": false,       # optional, defaults to true (GitHub default)
#     "max-size": 256           # optional guard rail; generation fails if exceeded
#   }
#
# The resolved output is shaped for direct consumption via `fromJson`:
#
#   {
#     "matrix": { "include": [ { ...combination... }, ... ] },
#     "size": <int>,
#     "max-parallel": <int|null>,
#     "fail-fast": <bool>
#   }
#
# Using `{ "include": [...] }` as the matrix is the canonical "dynamic matrix"
# idiom: each fully-resolved combination becomes one matrix job.
#

Set-StrictMode -Version Latest

# ---------------------------------------------------------------------------
# Input adapters: accept either a PSCustomObject (the JSON shape) or an
# IDictionary (handy for programmatic callers / tests) and read them uniformly.
# ---------------------------------------------------------------------------

function Get-ObjectKey {
    [CmdletBinding()]
    param([Parameter(Mandatory)] $InputObject)

    if ($null -eq $InputObject) { return @() }
    if ($InputObject -is [System.Collections.IDictionary]) {
        return @($InputObject.Keys)
    }
    # Enumerate properties explicitly rather than via `.PSObject.Properties.Name`
    # so an empty object is strict-mode safe (no member-enumeration on an empty
    # collection).
    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($prop in $InputObject.PSObject.Properties) { $names.Add($prop.Name) }
    return @($names.ToArray())
}

function Get-ObjectValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] $InputObject,
        [Parameter(Mandatory)] [string] $Key
    )

    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Collections.IDictionary]) {
        if ($InputObject.Contains($Key)) { return $InputObject[$Key] }
        return $null
    }
    $prop = $InputObject.PSObject.Properties[$Key]
    if ($prop) { return $prop.Value }
    return $null
}

function Test-ObjectHasKey {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] $InputObject,
        [Parameter(Mandatory)] [string] $Key
    )
    return (@(Get-ObjectKey $InputObject) -contains $Key)
}

# ---------------------------------------------------------------------------
# Dimension discovery + cartesian expansion
# ---------------------------------------------------------------------------

# Dimension keys are every key of the matrix object EXCEPT the reserved
# include/exclude rule lists.
function Get-MatrixDimensionName {
    [CmdletBinding()]
    param([Parameter(Mandatory)] $Matrix)

    $reserved = @('include', 'exclude')
    return @(Get-ObjectKey $Matrix | Where-Object { $reserved -notcontains $_ })
}

# Expand the cartesian product of all dimensions.
# The FIRST declared dimension varies slowest, matching GitHub Actions ordering.
# With zero dimensions we return an empty list (NOT a single empty combo) so that
# an include-only matrix yields exactly its include entries.
function Expand-MatrixCombination {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] $Matrix,
        [string[]] $DimensionName = @()
    )

    if ($DimensionName.Count -eq 0) { return @() }

    # Seed with one empty ordered combo, then fold each dimension in.
    $combos = @([ordered]@{})
    foreach ($name in $DimensionName) {
        $values = @(Get-ObjectValue $Matrix $name)
        if ($values.Count -eq 0) {
            # A dimension with no values collapses the whole product to empty,
            # exactly like an empty array would in GitHub Actions.
            return @()
        }
        $next = [System.Collections.Generic.List[object]]::new()
        foreach ($combo in $combos) {
            foreach ($value in $values) {
                $clone = [ordered]@{}
                foreach ($k in $combo.Keys) { $clone[$k] = $combo[$k] }
                $clone[$name] = $value
                $next.Add($clone)
            }
        }
        $combos = $next.ToArray()
    }
    return @($combos)
}

# ---------------------------------------------------------------------------
# exclude / include rule resolution (GitHub Actions semantics)
# ---------------------------------------------------------------------------

# A combination is excluded when EVERY key:value pair of an exclude rule matches
# it (a partial match is enough to exclude — extra combo keys are ignored).
function Remove-ExcludedCombination {
    [CmdletBinding()]
    param(
        $Combination = @(),
        $ExcludeRule
    )

    $Combination = @($Combination)
    if ($null -eq $ExcludeRule) { return @($Combination) }

    $kept = [System.Collections.Generic.List[object]]::new()
    foreach ($combo in $Combination) {
        $excluded = $false
        foreach ($rule in @($ExcludeRule)) {
            $matchesAll = $true
            foreach ($key in Get-ObjectKey $rule) {
                $ruleVal = Get-ObjectValue $rule $key
                if (-not $combo.Contains($key) -or "$($combo[$key])" -ne "$ruleVal") {
                    $matchesAll = $false
                    break
                }
            }
            if ($matchesAll) { $excluded = $true; break }
        }
        if (-not $excluded) { $kept.Add($combo) }
    }
    return @($kept.ToArray())
}

# Apply include rules using GitHub's documented algorithm:
#   * For each include rule, try to merge it into every ORIGINAL matrix combo.
#     A merge is allowed only when the rule does not overwrite an ORIGINAL matrix
#     value (i.e. for every rule key that is also a dimension, the values match).
#   * Merging adds/overwrites NON-original keys (e.g. keys added by an earlier
#     include rule may be overwritten).
#   * A rule that merges into no combo becomes a brand-new standalone combo.
#     Standalone combos are NOT eligible for later include merges.
function Add-IncludedCombination {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)] [AllowEmptyCollection()] [object[]] $Combination,
        $IncludeRule,
        [Parameter(Mandatory)] [AllowEmptyCollection()] [string[]] $DimensionName
    )

    # Work on mutable copies so we can merge in place.
    $base = [System.Collections.Generic.List[object]]::new()
    foreach ($combo in $Combination) {
        $copy = [ordered]@{}
        foreach ($k in $combo.Keys) { $copy[$k] = $combo[$k] }
        $base.Add($copy)
    }

    if ($null -eq $IncludeRule) { return @($base.ToArray()) }

    $appended = [System.Collections.Generic.List[object]]::new()
    foreach ($rule in @($IncludeRule)) {
        $ruleKeys = Get-ObjectKey $rule
        $mergedAny = $false

        foreach ($combo in $base) {
            # Compatible if no rule key that is a dimension would overwrite the
            # combo's original (dimension) value.
            $compatible = $true
            foreach ($key in $ruleKeys) {
                if ($DimensionName -contains $key) {
                    $ruleVal = Get-ObjectValue $rule $key
                    if ("$($combo[$key])" -ne "$ruleVal") { $compatible = $false; break }
                }
            }
            if ($compatible) {
                foreach ($key in $ruleKeys) {
                    $combo[$key] = Get-ObjectValue $rule $key
                }
                $mergedAny = $true
            }
        }

        if (-not $mergedAny) {
            $new = [ordered]@{}
            foreach ($key in $ruleKeys) { $new[$key] = Get-ObjectValue $rule $key }
            $appended.Add($new)
        }
    }

    $result = [System.Collections.Generic.List[object]]::new()
    foreach ($c in $base) { $result.Add($c) }
    foreach ($c in $appended) { $result.Add($c) }
    return @($result.ToArray())
}

# ---------------------------------------------------------------------------
# Public entry point
# ---------------------------------------------------------------------------

function New-BuildMatrix {
    <#
    .SYNOPSIS
        Resolve a declarative matrix configuration into a GitHub Actions matrix.
    .PARAMETER Config
        A PSCustomObject (typically from ConvertFrom-Json) or IDictionary holding
        `matrix`, and optionally `max-parallel`, `fail-fast`, and `max-size`.
    .OUTPUTS
        An ordered hashtable: matrix(.include), size, max-parallel, fail-fast.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory)] $Config)

    if ($null -eq $Config) {
        throw 'Configuration is null. Provide a config object with a "matrix" section.'
    }

    $matrix = Get-ObjectValue $Config 'matrix'
    if ($null -eq $matrix) {
        throw 'Configuration is missing the required "matrix" section.'
    }

    $hasInclude = Test-ObjectHasKey $matrix 'include'
    # @(...) keeps this an array even when a single dimension would otherwise be
    # unwrapped to a bare string by PowerShell's output pipeline.
    $dimensionNames = @(Get-MatrixDimensionName $matrix)

    if ($dimensionNames.Count -eq 0 -and -not $hasInclude) {
        throw 'The "matrix" section must define at least one dimension or an "include" list.'
    }

    # 1. cartesian product of the declared dimensions
    $combos = @(Expand-MatrixCombination -Matrix $matrix -DimensionName $dimensionNames)

    # 2. apply exclude rules
    $excludeRule = if (Test-ObjectHasKey $matrix 'exclude') { Get-ObjectValue $matrix 'exclude' } else { $null }
    $combos = @(Remove-ExcludedCombination -Combination $combos -ExcludeRule $excludeRule)

    # 3. apply include rules
    $includeRule = if ($hasInclude) { Get-ObjectValue $matrix 'include' } else { $null }
    $combos = @(Add-IncludedCombination -Combination $combos -IncludeRule $includeRule -DimensionName $dimensionNames)

    $size = $combos.Count

    # 4. validate against the optional maximum size guard rail
    if (Test-ObjectHasKey $Config 'max-size') {
        $maxSize = [int](Get-ObjectValue $Config 'max-size')
        if ($size -gt $maxSize) {
            throw "Generated matrix has $size combinations, which exceeds the configured max-size of $maxSize. Reduce dimensions/values or raise max-size."
        }
    }

    if ($size -eq 0) {
        throw 'The resolved matrix is empty. Check your dimensions and exclude rules.'
    }

    # 5. resolve strategy knobs
    $maxParallel = $null
    if (Test-ObjectHasKey $Config 'max-parallel') {
        $maxParallel = [int](Get-ObjectValue $Config 'max-parallel')
        if ($maxParallel -lt 1) {
            throw "max-parallel must be a positive integer, got '$maxParallel'."
        }
    }

    $failFast = $true  # GitHub Actions default
    if (Test-ObjectHasKey $Config 'fail-fast') {
        $failFast = [bool](Get-ObjectValue $Config 'fail-fast')
    }

    return [ordered]@{
        matrix        = [ordered]@{ include = @($combos) }
        size          = $size
        'max-parallel' = $maxParallel
        'fail-fast'   = $failFast
    }
}

# Serialize a resolved matrix to compact JSON suitable for fromJson().
function ConvertTo-MatrixJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, ValueFromPipeline)] $Matrix,
        [int] $Depth = 12,
        [switch] $Compress
    )
    process {
        # ConvertTo-Json renders a single-element array as a bare object; force a
        # JSON array for matrix.include so fromJson() always sees a list.
        return ($Matrix | ConvertTo-Json -Depth $Depth -Compress:$Compress)
    }
}

Export-ModuleMember -Function `
    New-BuildMatrix, ConvertTo-MatrixJson, `
    Get-MatrixDimensionName, Expand-MatrixCombination, `
    Remove-ExcludedCombination, Add-IncludedCombination, `
    Get-ObjectKey, Get-ObjectValue, Test-ObjectHasKey

#requires -Modules Pester

# Pester 5 unit tests for the build-matrix generator.
# Methodology: each test was written RED first, then the minimum code added to
# MatrixGenerator.psm1 to make it GREEN. Configs are built the same way the real
# CLI builds them (via ConvertFrom-Json) so the tests exercise the production path.

BeforeAll {
    $script:ModulePath = Join-Path $PSScriptRoot 'MatrixGenerator.psm1'
    Import-Module $script:ModulePath -Force

    # Helper: turn a JSON literal into the same PSCustomObject shape the CLI feeds
    # to New-BuildMatrix, so tests and production share one input path.
    function ConvertToConfig([string]$Json) {
        $Json | ConvertFrom-Json
    }

    # Combos in the resolved matrix are ordered dictionaries. Render one (and an
    # expected hashtable) to a stable, key-sorted "k=v;k=v" string so an exact
    # whole-combination comparison reads cleanly via Should -Be.
    function ComboString($Combo) {
        ($Combo.Keys | Sort-Object | ForEach-Object { "$_=$($Combo[$_])" }) -join ';'
    }
    function ExpectedString([hashtable]$Expected) {
        ($Expected.Keys | Sort-Object | ForEach-Object { "$_=$($Expected[$_])" }) -join ';'
    }
}

Describe 'New-BuildMatrix - cartesian product' {
    It 'produces the full cross product of two dimensions in declaration order' {
        $config = ConvertToConfig @'
{ "matrix": { "os": ["ubuntu-latest", "windows-latest"], "node": ["18", "20"] } }
'@
        $result = New-BuildMatrix -Config $config

        $result.size | Should -Be 4
        $combos = $result.matrix.include

        # First dimension varies slowest (matches GitHub Actions ordering).
        $combos[0].os   | Should -Be 'ubuntu-latest'; $combos[0].node | Should -Be '18'
        $combos[1].os   | Should -Be 'ubuntu-latest'; $combos[1].node | Should -Be '20'
        $combos[2].os   | Should -Be 'windows-latest'; $combos[2].node | Should -Be '18'
        $combos[3].os   | Should -Be 'windows-latest'; $combos[3].node | Should -Be '20'
    }
}

Describe 'New-BuildMatrix - exclude rules' {
    It 'removes combinations that fully match an exclude rule' {
        $config = ConvertToConfig @'
{ "matrix": {
    "os": ["ubuntu-latest", "windows-latest"],
    "node": ["18", "20"],
    "exclude": [ { "os": "windows-latest", "node": "18" } ]
} }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 3
        # The windows-latest/18 pair must be gone; the windows-latest/20 stays.
        $combos = $result.matrix.include
        ($combos | Where-Object { $_.os -eq 'windows-latest' -and $_.node -eq '18' }).Count | Should -Be 0
        ($combos | Where-Object { $_.os -eq 'windows-latest' -and $_.node -eq '20' }).Count | Should -Be 1
    }

    It 'treats an exclude rule as a partial match (one key is enough)' {
        $config = ConvertToConfig @'
{ "matrix": {
    "os": ["ubuntu-latest", "windows-latest", "macos-latest"],
    "node": ["18", "20"],
    "exclude": [ { "os": "macos-latest" } ]
} }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 4
        ($result.matrix.include | Where-Object { $_.os -eq 'macos-latest' }).Count | Should -Be 0
    }
}

Describe 'New-BuildMatrix - include rules' {
    It 'extends a matching combination with extra properties (feature flags)' {
        $config = ConvertToConfig @'
{ "matrix": {
    "os": ["ubuntu-latest", "windows-latest"],
    "node": ["18", "20"],
    "include": [ { "os": "ubuntu-latest", "node": "20", "experimental": true } ]
} }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 4   # no new rows, just an added property
        $target = $result.matrix.include | Where-Object { $_.os -eq 'ubuntu-latest' -and $_.node -eq '20' }
        $target.experimental | Should -BeTrue
        # Non-matching combos must NOT gain the property.
        $other = $result.matrix.include | Where-Object { $_.os -eq 'windows-latest' -and $_.node -eq '18' }
        $other.Contains('experimental') | Should -BeFalse
    }

    It 'adds a standalone combination when the include matches nothing' {
        $config = ConvertToConfig @'
{ "matrix": {
    "os": ["ubuntu-latest"],
    "node": ["18"],
    "include": [ { "os": "macos-latest", "node": "21", "experimental": true } ]
} }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 2
        $extra = $result.matrix.include | Where-Object { $_.os -eq 'macos-latest' }
        $extra.node | Should -Be '21'
        $extra.experimental | Should -BeTrue
    }

    It 'reproduces the canonical GitHub Actions include example exactly' {
        # https://docs.github.com/actions ... matrix include documented example.
        $config = ConvertToConfig @'
{ "matrix": {
    "fruit": ["apple", "pear"],
    "animal": ["cat", "dog"],
    "include": [
        { "color": "green" },
        { "color": "pink", "animal": "cat" },
        { "fruit": "apple", "shape": "circle" },
        { "fruit": "banana" },
        { "fruit": "banana", "animal": "cat" }
    ]
} }
'@
        $result = New-BuildMatrix -Config $config
        $c = $result.matrix.include
        $result.size | Should -Be 6

        ComboString $c[0] | Should -Be (ExpectedString @{ fruit='apple'; animal='cat'; color='pink';  shape='circle' })
        ComboString $c[1] | Should -Be (ExpectedString @{ fruit='apple'; animal='dog'; color='green'; shape='circle' })
        ComboString $c[2] | Should -Be (ExpectedString @{ fruit='pear';  animal='cat'; color='pink' })
        ComboString $c[3] | Should -Be (ExpectedString @{ fruit='pear';  animal='dog'; color='green' })
        ComboString $c[4] | Should -Be (ExpectedString @{ fruit='banana' })
        ComboString $c[5] | Should -Be (ExpectedString @{ fruit='banana'; animal='cat' })
    }

    It 'supports an include-only matrix (no base dimensions)' {
        $config = ConvertToConfig @'
{ "matrix": { "include": [
    { "os": "ubuntu-latest", "node": "18" },
    { "os": "windows-latest", "node": "20" }
] } }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 2
        $result.matrix.include[0].os | Should -Be 'ubuntu-latest'
        $result.matrix.include[1].os | Should -Be 'windows-latest'
    }
}

Describe 'New-BuildMatrix - feature flags as a dimension' {
    It 'expands boolean feature flags across the product and preserves type' {
        $config = ConvertToConfig @'
{ "matrix": {
    "os": ["ubuntu-latest"],
    "experimental": [true, false]
} }
'@
        $result = New-BuildMatrix -Config $config
        $result.size | Should -Be 2
        $result.matrix.include[0].experimental | Should -BeOfType [bool]
        $result.matrix.include[0].experimental | Should -BeTrue
        $result.matrix.include[1].experimental | Should -BeFalse
    }
}

Describe 'New-BuildMatrix - strategy knobs' {
    It 'passes through max-parallel and fail-fast' {
        $config = ConvertToConfig @'
{ "matrix": { "os": ["ubuntu-latest", "windows-latest"] },
  "max-parallel": 2, "fail-fast": false }
'@
        $result = New-BuildMatrix -Config $config
        $result.'max-parallel' | Should -Be 2
        $result.'fail-fast' | Should -BeFalse
    }

    It 'defaults fail-fast to true and max-parallel to null when omitted' {
        $config = ConvertToConfig '{ "matrix": { "os": ["ubuntu-latest"] } }'
        $result = New-BuildMatrix -Config $config
        $result.'fail-fast' | Should -BeTrue
        $result.'max-parallel' | Should -BeNullOrEmpty
    }

    It 'rejects a non-positive max-parallel with a clear message' {
        $config = ConvertToConfig '{ "matrix": { "os": ["ubuntu-latest"] }, "max-parallel": 0 }'
        { New-BuildMatrix -Config $config } | Should -Throw '*max-parallel must be a positive integer*'
    }
}

Describe 'New-BuildMatrix - max-size validation' {
    It 'succeeds when the matrix is within max-size' {
        $config = ConvertToConfig @'
{ "matrix": { "os": ["ubuntu-latest", "windows-latest"], "node": ["18", "20"] },
  "max-size": 4 }
'@
        { New-BuildMatrix -Config $config } | Should -Not -Throw
    }

    It 'fails with a meaningful error when the matrix exceeds max-size' {
        $config = ConvertToConfig @'
{ "matrix": { "os": ["ubuntu-latest", "windows-latest"], "node": ["18", "20", "22"] },
  "max-size": 4 }
'@
        { New-BuildMatrix -Config $config } |
            Should -Throw '*6 combinations, which exceeds the configured max-size of 4*'
    }
}

Describe 'New-BuildMatrix - error handling' {
    It 'throws when the config is null' {
        { New-BuildMatrix -Config $null } | Should -Throw '*null*'
    }

    It 'throws when the matrix section is missing' {
        $config = ConvertToConfig '{ "max-parallel": 2 }'
        { New-BuildMatrix -Config $config } | Should -Throw '*missing the required "matrix" section*'
    }

    It 'throws when there are no dimensions and no include list' {
        $config = ConvertToConfig '{ "matrix": { } }'
        { New-BuildMatrix -Config $config } | Should -Throw '*at least one dimension or an "include" list*'
    }

    It 'throws when every combination is excluded' {
        $config = ConvertToConfig @'
{ "matrix": { "os": ["ubuntu-latest"], "exclude": [ { "os": "ubuntu-latest" } ] } }
'@
        { New-BuildMatrix -Config $config } | Should -Throw '*resolved matrix is empty*'
    }
}

Describe 'ConvertTo-MatrixJson - output shape' {
    It 'round-trips through fromJson-style parsing with include as an array' {
        $config = ConvertToConfig '{ "matrix": { "os": ["ubuntu-latest"], "node": ["18"] } }'
        $json = New-BuildMatrix -Config $config | ConvertTo-MatrixJson -Compress
        $parsed = $json | ConvertFrom-Json
        # include must be a JSON array even with a single element.
        @($parsed.matrix.include).Count | Should -Be 1
        $parsed.matrix.include[0].os | Should -Be 'ubuntu-latest'
        $parsed.size | Should -Be 1
    }
}

